   120		if (unknownFlags.length > 0) {
   121			diagnostics.push({
   122				type: "error",
   123				message: `Unknown option${unknownFlags.length === 1 ? "" : "s"}: ${unknownFlags.map((name) => `--${name}`).join(", ")}`,
