   105			}
   106			if (flag.type === "boolean") {
   107				extensionsResult.runtime.flagValues.set(name, true);
   108				continue;
   109			}
   110			if (typeof value === "string") {
   111				extensionsResult.runtime.flagValues.set(name, value);
   112				continue;
   113			}
   114			diagnostics.push({
   115				type: "error",
   116				message: `Extension flag "--${name}" requires a value`,
   117			});
   118		}
