  1060				...request,
  1061				model,
  1062				previous: previousModel && { model: previousModel, thinkingLevel: latest?.thinkingLevel },
  1063				failed: failedModel && failed && { model: failedModel, thinkingLevel: failed.thinkingLevel, message: failed },
  1064				messages,
  1065			});
