  1067			const routed = `${name} routed to ${route.model.provider}/${route.model.id}`;
  1068			if (!target) throw new Error(`${routed}, which is not a physical model.`);
  1069			if (!this.hasConfiguredAuth(target.provider)) throw new Error(`${routed}, which has no credentials.`);
